// amplify_outputs.json is generated by the Amplify backend deploy and holds the
// backend functions' URLs. Not a secret: the function checks the access
// code and keeps the OpenAI key to itself.
const outputs = Object.values(import.meta.glob('../amplify_outputs.json', { eager: true, import: 'default' }))[0]
export const TOKEN_URL = outputs?.custom?.sessionTokenUrl
export const REPORT_URL = outputs?.custom?.coachReportUrl

// Calls hang up automatically after this many seconds.
export const MAX_CALL_SECONDS = 5 * 60
